<script>
  // Vayu — /pages/journal-post.html, ported from public/pages/journal-post.html.
  import { onMount } from 'svelte';

  // Emitted through {@html} rather than written as a component <style>:
  // Svelte scopes component styles, and these selectors target markup
  // that the global stylesheet and other components own.
  const pageCss = "<style>/* ---- article page ------------------------------------------------\n       The destination the Journal listing's cards always promised. Every\n       card and the featured block used to be href=\"javascript:void(0)\".\n       ------------------------------------------------------------------ */\n    .post-page {\n      padding-bottom: 80px;\n    }\n\n    .post-hero {\n      position: relative;\n      width: 100%;\n      aspect-ratio: 21 / 9;\n      overflow: hidden;\n      background: #FAF8F5;\n      margin-bottom: 34px;\n    }\n\n    .post-hero img {\n      width: 100%;\n      height: 100%;\n      object-fit: cover;\n    }\n\n    /* one measured column for reading, centred in the page column */\n    .post-body-wrap {\n      max-width: 46em;\n      margin: 0 auto;\n    }\n\n    .post-cat {\n      display: inline-block;\n      font-family: 'Jost', sans-serif;\n      font-size: 10px;\n      letter-spacing: 0.2em;\n      text-transform: uppercase;\n      font-weight: 600;\n      color: var(--accent);\n      margin-bottom: 12px;\n    }\n\n    .post-title {\n      font-family: 'Cormorant Garamond', serif;\n      font-size: clamp(30px, 4vw, 50px);\n      font-weight: 400;\n      line-height: 1.1;\n      color: var(--ink);\n      margin-bottom: 14px;\n    }\n\n    .post-meta {\n      display: flex;\n      flex-wrap: wrap;\n      align-items: center;\n      gap: 10px;\n      font-family: 'Jost', sans-serif;\n      font-size: 11px;\n      letter-spacing: 0.14em;\n      text-transform: uppercase;\n      color: #8A8681;\n      margin-bottom: 26px;\n      padding-bottom: 20px;\n      /* drawn as a background so the flat layer's transparent border-color\n         cannot erase it */\n      background-image: linear-gradient(#EFEAE1, #EFEAE1);\n      background-size: 100% 1px;\n      background-position: 0 100%;\n      background-repeat: no-repeat;\n    }\n\n    .post-meta-dot {\n      color: #C3BDB3;\n    }\n\n    .post-lead {\n      font-family: 'Cormorant Garamond', serif;\n      font-size: clamp(18px, 2vw, 22px);\n      font-weight: 400;\n      font-style: italic;\n      line-height: 1.55;\n      color: var(--ink);\n      margin-bottom: 26px;\n    }\n\n    .post-body p {\n      font-size: 15.5px;\n      line-height: 1.85;\n      color: var(--body);\n      margin-bottom: 20px;\n    }\n\n    /* Shown when a story has no `body` paragraphs yet. Deliberately an\n       honest editorial placeholder rather than invented copy \u2014 see the\n       authoring notes in js/journal-data.js. */\n    .post-pending {\n      background: #FAF8F5;\n      padding: 22px 24px;\n      margin-bottom: 28px;\n    }\n\n    .post-pending h2 {\n      font-family: 'Jost', sans-serif;\n      font-size: 10.5px;\n      letter-spacing: 0.18em;\n      text-transform: uppercase;\n      font-weight: 600;\n      color: var(--ink);\n      margin-bottom: 8px;\n    }\n\n    .post-pending p {\n      font-size: 14px;\n      line-height: 1.7;\n      color: var(--body);\n      margin: 0;\n    }\n\n    .post-foot {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 12px;\n      justify-content: space-between;\n      align-items: center;\n      margin-top: 40px;\n      padding-top: 24px;\n      background-image: linear-gradient(#EFEAE1, #EFEAE1);\n      background-size: 100% 1px;\n      background-position: 0 0;\n      background-repeat: no-repeat;\n    }\n\n    .post-back,\n    .post-next {\n      display: inline-flex;\n      align-items: center;\n      gap: 8px;\n      font-family: 'Jost', sans-serif;\n      font-size: 11px;\n      letter-spacing: 0.16em;\n      text-transform: uppercase;\n      font-weight: 500;\n      color: var(--ink);\n      transition: color 0.2s ease;\n    }\n\n    .post-back:hover,\n    .post-next:hover {\n      color: var(--accent);\n    }\n\n    .post-next {\n      text-align: right;\n      max-width: 60%;\n    }\n\n    /* ---- more stories ---- */\n    .post-more {\n      margin-top: 60px;\n    }\n\n    .post-more-grid {\n      display: grid;\n      grid-template-columns: repeat(3, minmax(0, 1fr));\n      gap: 24px;\n    }\n\n    .post-more-card {\n      display: flex;\n      flex-direction: column;\n    }\n\n    .post-more-media {\n      display: block;\n      overflow: hidden;\n      aspect-ratio: 4 / 3;\n      background: #FAF8F5;\n      margin-bottom: 12px;\n    }\n\n    .post-more-media img {\n      width: 100%;\n      height: 100%;\n      object-fit: cover;\n      transition: transform 0.6s cubic-bezier(0.25, 1, 0.5, 1);\n    }\n\n    .post-more-card:hover .post-more-media img {\n      transform: scale(1.04);\n    }\n\n    .post-more-cat {\n      font-family: 'Jost', sans-serif;\n      font-size: 9.5px;\n      letter-spacing: 0.18em;\n      text-transform: uppercase;\n      color: var(--gold);\n      font-weight: 500;\n      margin-bottom: 5px;\n    }\n\n    .post-more-title {\n      font-family: 'Cormorant Garamond', serif;\n      font-size: 19px;\n      font-weight: 500;\n      line-height: 1.25;\n      color: var(--ink);\n      transition: color 0.2s ease;\n    }\n\n    .post-more-card:hover .post-more-title {\n      color: var(--accent);\n    }\n\n    /* ---- story not found ---- */\n    .post-missing {\n      padding: 70px 16px 90px;\n      text-align: center;\n    }\n\n    @media (max-width: 1023px) {\n      .post-more-grid {\n        grid-template-columns: repeat(2, minmax(0, 1fr));\n      }\n    }\n\n    @media (max-width: 768px) {\n      .post-hero {\n        aspect-ratio: 4 / 3;\n        margin-bottom: 24px;\n      }\n\n      .post-more-grid {\n        grid-template-columns: 1fr;\n        gap: 20px;\n      }\n\n      .post-next {\n        max-width: 100%;\n      }\n    }</style>";

  onMount(() => {
    import('#lib/pages/journal-post.js').then(m => m.default?.());
  });
</script>

<svelte:head>
